package tr.akilliklavye;
import android.inputmethodservice.InputMethodService;import android.graphics.Color;import android.view.*;import android.view.inputmethod.InputConnection;import android.widget.*;
public class KeyboardService extends InputMethodService {
 boolean shift=false; boolean symbols=false; LinearLayout root;
 @Override public View onCreateInputView(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(3,5,3,5);root.setBackgroundColor(Color.rgb(220,224,230));render();return root;}
 void render(){root.removeAllViews();String[] rows=symbols?new String[]{"1234567890","@#₺%&-+()","*':;!?"}:new String[]{"qwertyuıopğü","asdfghjklşi","zxcvbnmöç"};for(String s:rows){LinearLayout line=new LinearLayout(this);for(char ch:s.toCharArray()){Button b=key(String.valueOf(shift?Character.toUpperCase(ch):ch),1);b.setOnClickListener(v->send(String.valueOf(shift?Character.toUpperCase(ch):ch)));line.addView(b);}root.addView(line);}LinearLayout controls=new LinearLayout(this);Button mode=key(symbols?"ABC":"?123",1);mode.setOnClickListener(v->{symbols=!symbols;render();});controls.addView(mode);Button cap=key("⇧",1);cap.setOnClickListener(v->{shift=!shift;render();});controls.addView(cap);Button space=key("Boşluk",4);space.setOnClickListener(v->send(" "));controls.addView(space);Button del=key("⌫",1);del.setOnClickListener(v->{InputConnection ic=getCurrentInputConnection();if(ic!=null)ic.deleteSurroundingText(1,0);});controls.addView(del);Button enter=key("↵",1);enter.setOnClickListener(v->send("\n"));controls.addView(enter);root.addView(controls);}
 Button key(String s,int w){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);b.setPadding(0,0,0,0);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,(int)(52*getResources().getDisplayMetrics().density),w);p.setMargins(1,1,1,1);b.setLayoutParams(p);return b;}
 void send(String s){InputConnection ic=getCurrentInputConnection();if(ic!=null)ic.commitText(s,1);}
}